    }

    public static void removeBookmark(Context ctx, int id) {
        ArrayList<Bookmark> bookmarks = loadBookmarks(ctx, false);

        for (Bookmark bookmark: bookmarks) {
            if (bookmark.id == id) {
                bookmarks.remove(bookmark);
                break;
            }
        }

        saveBookmarks(ctx, bookmarks);
    }

